<?php use App\Support; $fields = Support::decode($order['form_fields_json']); $codes = Support::decode($order['event_codes_json']); $canCancel = in_array((string) $order['source_status'], ['processing', 'pending'], true) && in_array((string) $order['processing_status'], ['received', 'mapping_required', 'ready', 'retry_waiting', 'manual_review', 'failed'], true) && !$targets; ?>
<div class="page-head"><div><a class="back-link" href="/orders">← Quay lại danh sách</a><span class="eyebrow">ĐƠN #<?= (int)$order['nas_order_id'] ?></span><h1><?= Support::e($order['nas_product_name']) ?></h1><p><?= Support::e($order['customer_username'] ? '@'.$order['customer_username'] : trim($order['customer_first_name'].' '.$order['customer_last_name'])) ?> · Telegram <?= Support::e($order['customer_telegram_id']) ?></p></div><div class="head-actions"><span class="badge large <?= Support::badgeClass($order['processing_status']) ?>"><?= Support::e(Support::statusLabel($order['processing_status'])) ?></span><?php if ($canCancel): ?><form method="post" action="/order/cancel" onsubmit="return confirm('Bạn chắc chắn muốn huỷ đơn này? Nas Tele sẽ gửi thông báo huỷ cho khách.')"><input type="hidden" name="_csrf" value="<?= Support::csrfToken() ?>"><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="cancel_reason" value="Đơn được huỷ thủ công do không thể xử lý."><button class="btn danger-button">Huỷ đơn</button></form><?php endif; ?><form method="post" action="/order/retry"><input type="hidden" name="_csrf" value="<?= Support::csrfToken() ?>"><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><button class="btn secondary">Xử lý lại đơn</button></form></div></div>
<section class="order-timeline dark-field"><article class="done"><i>1</i><div><b>Nhận đơn</b><span><?= Support::e($order['source_created_at'] ?: $order['created_at']) ?></span></div></article><article class="<?= $order['mapping_id'] ? 'done' : '' ?>"><i>2</i><div><b>Kiểm tra sản phẩm</b><span><?= $order['mapping_id'] ? 'Đã tìm thấy liên kết' : 'Chưa liên kết sản phẩm' ?></span></div></article><article class="<?= $targets ? 'done' : '' ?>"><i>3</i><div><b>Xử lý trên Chungsucliqi</b><span><?= $targets ? Support::e($targets[0]['target_order_code'] ?: 'Đã gửi đơn') : 'Chưa gửi đơn' ?></span></div></article><article class="<?= $order['source_sync_status'] === 'synced' ? 'done' : '' ?>"><i>4</i><div><b>Báo kết quả</b><span><?= Support::e(Support::syncStatusLabel($order['source_sync_status'])) ?></span></div></article></section>
<div class="detail-grid"><section class="panel"><div class="section-head"><div><h2>Thông tin khách đã nhập</h2><p>Dữ liệu nhận từ Nas Tele.</p></div></div><dl class="field-list"><?php foreach ($fields as $field): ?><div><dt><?= Support::e($field['label'] ?? $field['key'] ?? '') ?></dt><dd><?= nl2br(Support::e(is_scalar($field['value'] ?? null) ? $field['value'] : Support::json($field['value'] ?? null))) ?></dd></div><?php endforeach; ?><?php if (!$fields): ?><div class="empty">Chưa nhận được thông tin khách nhập.</div><?php endif; ?></dl></section><section class="panel"><div class="section-head"><div><h2>Tình trạng đơn</h2><p>Thông tin xử lý hiện tại.</p></div></div><dl class="summary-list"><div><dt>Mã chung sức</dt><dd><?= Support::e(implode(', ', $codes)) ?: '—' ?></dd></div><div><dt>Tại Nas Tele</dt><dd><?= Support::e(Support::statusLabel($order['source_status'])) ?></dd></div><div><dt>Kết quả gửi về</dt><dd><?= Support::e(Support::syncStatusLabel($order['source_sync_status'])) ?></dd></div><div><dt>Thông báo cho khách</dt><dd><?= $order['notification_sent'] === null ? 'Chưa đến bước thông báo' : ($order['notification_sent'] ? 'Đã gửi thành công' : 'Gửi chưa thành công') ?></dd></div><div><dt>Số lần hệ thống thử lại</dt><dd><?= (int)$order['retry_count'] ?></dd></div></dl><?php if ($order['last_error']): ?><div class="notice danger"><b>Vấn đề gần nhất</b><span><?= Support::e(Support::friendlyMessage($order['last_error'])) ?></span></div><?php endif; ?></section></div>
<section class="panel"><div class="section-head"><div><h2>Thông tin từ Chungsucliqi</h2><p>Tình trạng và tiến độ thực hiện đơn.</p></div></div><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Cách đặt</th><th>Chi phí</th><th>Tiến độ</th><th>Trạng thái</th><th>Ghi chú</th></tr></thead><tbody><?php foreach ($targets as $target): ?><tr><td><b><?= Support::e($target['target_order_code']) ?></b></td><td><?= Support::e(Support::targetTypeLabel($target['target_type'])) ?></td><td><?= $target['price'] !== null ? number_format((float)$target['price']).' Xu' : '—' ?></td><td><?= $target['progress_percent'] !== null ? (int)$target['progress_percent'].'%' : '—' ?><small><?= $target['tickets_done'] !== null ? (int)$target['tickets_done'].' / '.(int)$target['tickets_total'].' vé' : '' ?></small></td><td><span class="badge <?= Support::badgeClass($target['status']) ?>"><?= Support::e(Support::statusLabel($target['status'])) ?></span></td><td><?= Support::e($target['message']) ?></td></tr><?php endforeach; ?><?php if (!$targets): ?><tr><td colspan="6" class="empty">Đơn chưa được gửi sang Chungsucliqi.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="section-head"><div><h2>Lịch sử xử lý</h2><p>Các hoạt động và vấn đề đã xảy ra với đơn này.</p></div></div><div class="log-list"><?php foreach ($logs as $log): ?><article><span class="log-dot <?= Support::e($log['level']) ?>"></span><div><b><?= Support::e(Support::friendlyMessage($log['message'])) ?></b><small><?= Support::e(Support::channelLabel($log['channel']).' · '.$log['created_at']) ?></small></div></article><?php endforeach; ?><?php if (!$logs): ?><div class="empty">Chưa có hoạt động nào được ghi nhận.</div><?php endif; ?></div></section>
